    let show = match level {
        "WARN" => true,
        "INFO" => v >= 1,
        "DEBUG" => v >= 2,
        _ => true,
    };
    if show {
        let mut out = io::stdout().lock();
        let _ = writeln!(out, "{} [{}] {}", timestamp(), level, msg);
        let _ = out.flush();
    }
}
