// ---------- Progress ----------
fn human_bytes(n: u64) -> String {
    if n < 1024 {
        return format!("{} B", n);
    }
    let units = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
    let mut v = n as f64;
    let mut idx = 0usize;
    // convert to KiB first
    v /= 1024.0;
    while v >= 1024.0 && idx + 1 < units.len() {
        v /= 1024.0;
        idx += 1;
    }
    format!("{:.2} {}", v, units[idx])
}
struct ProgressInner {
    total: u64,
    pos: u64,
    drawn: bool,
    start: Instant,
    last_draw: Option<Instant>,
}
struct Progress {
    enabled: bool,
    inner: Mutex<ProgressInner>,
}
impl Progress {
    fn new(enabled: bool) -> Self {
        Self { enabled, inner: Mutex::new(ProgressInner { total: 0, pos: 0, drawn: false, start: Instant::now(), last_draw: None }) }
    }
    fn draw_locked(&self, g: &mut ProgressInner, force: bool) {
        if !self.enabled { return; }
        if !force {
            if let Some(last) = g.last_draw {
                if last.elapsed().as_millis() < 10 && g.drawn {
                    return;
                }
            }
        }
        let line = self.make_line(g);
        let mut err = io::stderr().lock();
        if g.drawn {
            let _ = write!(err, "\r\x1b[2K{}", line);
        } else {
            let _ = write!(err, "{}", line);
        }
        let _ = err.flush();
        g.drawn = true;
        g.last_draw = Some(Instant::now());
    }
    fn make_line(&self, g: &ProgressInner) -> String {
        let (percent, bar) = if g.total == 0 {
            (100u64, "########".to_string())
        } else {
            let pct = ((g.pos as u128 * 100) / g.total as u128) as u64;
            let frac = g.pos as f64 / g.total as f64;
            let filled = ((frac * 8.0).floor() as usize).min(8);
            let mut b = String::new();
            if g.pos == 0 {
                b.push_str("--------");
            } else if g.pos >= g.total {
                b.push_str("########");
            } else {
                for i in 0..8 {
                    if i < filled { b.push('#'); }
                    else if i == filled { b.push('>'); }
                    else { b.push('-'); }
                }
            }
            (pct, b)
        };
        let elapsed = g.start.elapsed().as_secs_f64();
        let speed: f64 = if elapsed > 0.0 { g.pos as f64 / elapsed } else { 0.0 };
        let speed_str = format!("{}/s", human_bytes(speed as u64));
        // indicatif bytes_per_sec formats fractional for e.g. MiB: human_bytes with speed float?
        // We need more precise speed formatting for non-integer scales; handled below via human_speed
        let speed_str = human_speed(speed);
        let eta_secs: u64 = if g.pos == 0 || speed <= 0.0 || g.total <= g.pos {
            0
        } else {
            ((g.total - g.pos) as f64 / speed).floor() as u64
        };
        let eta = format!("{:02}:{:02}:{:02}", eta_secs / 3600, (eta_secs % 3600) / 60, eta_secs % 60);
        format!("[{}] {:>11} / {:<12}| {:>3}% | {:^13} | {} remaining", bar, human_bytes(g.pos), human_bytes(g.total), percent, speed_str, eta)
    }
    fn add_total(&self, n: u64) {
        if !self.enabled { return; }
        let mut g = self.inner.lock().unwrap();
        g.total = g.total.saturating_add(n);
        // Always draw on total change (mirrors directory walk behaviour)
        self.draw_locked(&mut g, true);
    }
    fn inc(&self, n: u64) {
        if !self.enabled || n == 0 { return; }
        let mut g = self.inner.lock().unwrap();
        g.pos = g.pos.saturating_add(n);
        self.draw_locked(&mut g, false);
    }
    fn finish(&self) {
        if !self.enabled { return; }
        let mut g = self.inner.lock().unwrap();
        // final draw always
        let line = self.make_line(&g);
        let mut err = io::stderr().lock();
        if g.drawn {
            let _ = write!(err, "\r\x1b[2K{}", line);
        } else {
            let _ = write!(err, "{}", line);
        }
        let _ = err.flush();
        g.drawn = true;
    }
    fn clear(&self) {
        if !self.enabled { return; }
        let g = self.inner.lock().unwrap();
        if g.drawn {
            let mut err = io::stderr().lock();
            let _ = write!(err, "\r\x1b[2K");
            let _ = err.flush();
        }
    }
}
fn human_speed(speed: f64) -> String {
    if speed < 1024.0 {
        return format!("{} B/s", speed as u64);
    }
    let units = ["KiB/s", "MiB/s", "GiB/s", "TiB/s", "PiB/s", "EiB/s"];
    let mut v = speed / 1024.0;
    let mut idx = 0usize;
    while v >= 1024.0 && idx + 1 < units.len() {
        v /= 1024.0;
        idx += 1;
    }
    format!("{:.2} {}", v, units[idx])
}

// ---------- Block size parsing ----------
fn parse_block_size(s: &str) -> Result<u64, String> {
    let trimmed = s.trim();
    if trimmed.is_empty() {
        // Replicate unbytify panic for empty input
        let tid = unsafe { libc::syscall(libc::SYS_gettid) };
        eprintln!("\nthread 'main' ({}) panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/unbytify-0.2.0/src/lib.rs:101:14:", tid);
        eprintln!("byte index 1 is out of bounds of ``");
        eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
        std::process::exit(101);
    }
    // Step 1: plain integer / plain float (no unit)
    if let Ok(v) = trimmed.parse::<u64>() {
        return Ok(v);
    }
    if let Ok(v) = trimmed.parse::<f64>() {
        if v.is_nan() {
            return Ok(0);
        }
        if v.is_infinite() {
            if v.is_sign_negative() { return Err("could not interpret string as byte size".to_string()); }
            return Ok(u64::MAX);
        }
        if v < 0.0 {
            return Err("could not interpret string as byte size".to_string());
        }
        if v.fract() == 0.0 {
            // saturating cast like Rust `as`
            return Ok(v as u64);
        } else {
            return Err("could not interpret string as byte size".to_string());
        }
    }
    // Step 2: numeric prefix + unit suffix (trailing alphabetic chars)
    let bytes = trimmed.as_bytes();
    let mut unit_start = bytes.len();
    while unit_start > 0 && bytes[unit_start - 1].is_ascii_alphabetic() {
        unit_start -= 1;
    }
    if unit_start == bytes.len() || unit_start == 0 {
        return Err("could not interpret string as byte size".to_string());
    }
    let num_str = trimmed[..unit_start].trim();
    let unit_str = &trimmed[unit_start..];
    if num_str.is_empty() {
        return Err("could not interpret string as byte size".to_string());
    }
    if num_str.starts_with('-') {
        return Err("could not interpret string as byte size".to_string());
    }
    let num: f64 = match num_str.parse::<f64>() {
        Ok(v) => v,
        Err(_) => return Err("could not interpret string as byte size".to_string()),
    };
    if num < 0.0 {
        return Err("could not interpret string as byte size".to_string());
    }
    let unit_lc = unit_str.to_ascii_lowercase();
    let mult: f64 = match unit_lc.as_str() {
        "b" => 1.0,
        "k" | "kb" => 1000.0,
        "kib" => 1024.0,
        "m" | "mb" => 1000f64.powi(2),
        "mib" => 1024f64.powi(2),
        "g" | "gb" => 1000f64.powi(3),
        "gib" => 1024f64.powi(3),
        "t" | "tb" => 1000f64.powi(4),
        "tib" => 1024f64.powi(4),
        "p" | "pb" => 1000f64.powi(5),
        "pib" => 1024f64.powi(5),
        "e" | "eb" => 1000f64.powi(6),
        "eib" => 1024f64.powi(6),
        _ => return Err("could not interpret string as byte size".to_string()),
    };
    let result = num * mult;
    if result.is_nan() {
        return Ok(0);
    }
    if result > u64::MAX as f64 || result.is_infinite() {
        return Err("byte size too large".to_string());
    }
    Ok(result as u64)
}

// ---------- Parsers for driver/reflink/backup ----------
fn parse_driver(s: &str) -> Result<Driver, String> {
    match s.to_ascii_lowercase().as_str() {
        "parfile" => Ok(Driver::Parfile),
        "parblock" => Ok(Driver::Parblock),
        _ => Err(format!("Unknown driver: {}", s)),
    }
}
fn parse_reflink(s: &str) -> Result<ReflinkMode, String> {
    match s.to_ascii_lowercase().as_str() {
        "auto" => Ok(ReflinkMode::Auto),
        "always" => Ok(ReflinkMode::Always),
        "never" => Ok(ReflinkMode::Never),
        _ => Err(format!("Invalid arguments: Unexpected value for 'reflink': {}", s)),
    }
}
fn parse_backup(s: &str) -> Result<BackupMode, String> {
    match s.to_ascii_lowercase().as_str() {
        "none" | "off" => Ok(BackupMode::None),
        "numbered" => Ok(BackupMode::Numbered),
        "auto" => Ok(BackupMode::Auto),
        _ => Err(format!("Invalid arguments: Unexpected value for 'backup': {}", s)),
    }
}

// ---------- CLI construction ----------
fn build_cli() -> Command {
    Command::new("xcp")
        .version("0.24.3")
        .about("A (partial) clone of the Unix `cp` command with progress and pluggable drivers.")
        .arg(
            Arg::new("PATHS")
                .help("Path list")
                .long_help("Path list.\n\nSource and destination files, or multiple source(s) to a directory.")
                .num_args(0..)
                .value_name("PATHS"),
        )
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .help("Verbosity")
                .long_help("Verbosity.\n\nCan be specified multiple times to increase logging.")
                .action(ArgAction::Count),
        )
        .arg(
            Arg::new("recursive")
                .short('r')
                .long("recursive")
                .help("Copy directories recursively")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("dereference")
                .short('L')
                .long("dereference")
                .help("Dereference symlinks in source")
                .long_help("Dereference symlinks in source\n\nFollow symlinks, possibly recursively, when copying source files.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("workers")
                .short('w')
                .long("workers")
                .help("Number of parallel workers")
                .long_help("Number of parallel workers.\n\nDefault is 4; if the value is negative or 0 it uses the number of logical CPUs.")
                .value_name("WORKERS")
                .default_value("4")
                .value_parser(clap::value_parser!(usize)),
        )
        .arg(
            Arg::new("block-size")
                .long("block-size")
                .help("Block size for operations")
                .long_help("Block size for operations.\n\nAccepts standard size modifiers like \"M\" and \"GB\". Actual usage internally depends on the driver.")
                .value_name("BLOCK_SIZE")
                .default_value("1MB")
                .value_parser(|s: &str| parse_block_size(s)),
        )
        .arg(
            Arg::new("no-clobber")
                .short('n')
                .long("no-clobber")
                .help("Do not overwrite an existing file")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("force")
                .short('f')
                .long("force")
                .help("Force (compatability only)")
                .long_help("Force (compatability only)\n\nOverwrite files; this is the default behaviour, this flag is for compatibility with `cp` only. See `--no-clobber` for the inverse flag. Using this in conjunction with `--no-clobber` will cause an error.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("gitignore")
                .long("gitignore")
                .help("Use .gitignore if present")
                .long_help("Use .gitignore if present.\n\nNOTE: This is fairly basic at the moment, and only honours a .gitignore in the directory root for directory copies; global or sub-directory ignores are skipped.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("glob")
                .short('g')
                .long("glob")
                .help("Expand file patterns")
                .long_help("Expand file patterns.\n\nGlob (expand) filename patterns natively (note; the shell may still do its own expansion first)")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("no-progress")
                .long("no-progress")
                .help("Disable progress bar")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("no-perms")
                .long("no-perms")
                .help("Do not copy the file permissions")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("no-timestamps")
                .long("no-timestamps")
                .help("Do not copy the file timestamps")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("ownership")
                .short('o')
                .long("ownership")
                .help("Copy ownership")
                .long_help("Copy ownership.\n\nWhether to copy ownship (user/group).  This option requires root permissions or appropriate capabilities; if the attempt to copy ownership fails a warning is issued but the operation continues.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("driver")
                .long("driver")
                .help("Driver to use, defaults to 'file-parallel'")
                .long_help("Driver to use, defaults to 'file-parallel'.\n\nCurrently there are 2; the default \"parfile\", which parallelises copies across workers at the file level, and an experimental \"parblock\" driver, which parellelises at the block level. See also '--block-size'.")
                .value_name("DRIVER")
                .default_value("parfile")
                .value_parser(|s: &str| parse_driver(s)),
        )
        .arg(
            Arg::new("no-target-directory")
                .short('T')
                .long("no-target-directory")
                .help("Target should not be a directory")
                .long_help("Target should not be a directory.\n\nAnalogous to cp's no-target-directory. Expected behavior is that when copying a directory to another directory, instead of creating a sub-folder in target, overwrite target.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("target-directory")
                .long("target-directory")
                .help("Copy into a subdirectory of the target")
                .value_name("TARGET_DIRECTORY"),
        )
        .arg(
            Arg::new("fsync")
                .long("fsync")
                .help("Sync each file to disk after writing")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("reflink")
                .long("reflink")
                .help("Reflink options")
                .long_help("Reflink options.\n\nWhether and how to use reflinks. 'auto' (the default) will attempt to reflink and fallback to a copy if it is not possible, 'always' will return an error if it cannot reflink, and 'never' will always perform a full data copy.\n\nNote: when using Linux accelerated copy operations (the default when available) the kernel may choose to reflink rather than perform a fully copy regardless of this setting.")
                .value_name("REFLINK")
                .default_value("auto")
                .value_parser(|s: &str| parse_reflink(s)),
        )
        .arg(
            Arg::new("backup")
                .long("backup")
                .help("Backup options")
                .long_help("Backup options\n\nWhether to create backups of overwritten files. Current options are 'none'/'off', or 'numbered', or 'auto'. Numbered backups follow the semantics of `cp` numbered backups (e.g. `file.txt.~123~`). 'auto' will only create a numbered backup if a previous backups exists. Default is 'none'.")
                .value_name("BACKUP")
                .default_value("none")
                .value_parser(|s: &str| parse_backup(s)),
        )
}

// ---------- Gitignore ----------
#[derive(Clone)]
struct GitPattern {
    negated: bool,
    dir_only: bool,
    anchored: bool,
    pattern: String, // without leading slash, without trailing slash
}
struct Gitignore {
    patterns: Vec<GitPattern>,
}
impl Gitignore {
    fn load(path: &Path) -> Option<Self> {
        let content = fs::read_to_string(path).ok()?;
        let mut patterns = Vec::new();
        for raw_line in content.lines() {
            let mut line = raw_line.to_string();
            // ignore crate skips invalid lines silently; we do same
            if line.ends_with('\r') { line.pop(); }
            // trailing spaces are ignored unless escaped (simplify: trim trailing unescaped spaces)
            // We handle escaped spaces later; basic trim
            let mut l = line.as_str();
            // skip empty / comments
            let trimmed_start = l.trim_start_matches(' ');
            // comment check on original (after optional ? gitignore: line starting with #)
            if l.is_empty() { continue; }
            if l.starts_with('#') { continue; }
            // Check if line is all spaces
            if l.trim().is_empty() { continue; }
            let mut negated = false;
            if let Some(rest) = l.strip_prefix('!') {
                negated = true;
                l = rest;
            } else if let Some(rest) = l.strip_prefix("\\!") {
                l = rest;
                // literal ! : we need to keep it as part of pattern; reconstruct
                // We'll prepend ! back as escaped char marker; simplest: pattern starts with !
                // Handle by keeping a placeholder: use '\u{1}'?
                // For simplicity, treat "\!" as "!"
                // We'll set l to a string starting with !
                // But we have &str; create owned below
                // Fallthrough handled via owned string path
                // To avoid complexity, we rebuild patterns via owned strings below.
                let _ = trimmed_start;
                // Use special handling: create pattern directly
                let mut pat = format!("!{}", l);
                // process trailing / etc below using pat clone
                // We'll push via helper
                // -- handled by continuing to generic owned processing
                // Set a flag by using owned variable
                // Instead, we will process via owned string 'owned' defined below.
                // To keep code simple, we reassign using leaked? No.
                // We'll just treat as literal '!' pattern:
                pat = pat; // no-op
                // Push manually
                // (dir_only etc)
                let mut dir_only = false;
                if pat.ends_with('/') { dir_only = true; pat = pat.trim_end_matches('/').to_string(); }
                let anchored = pat.contains('/');
                let pat_clean = pat.trim_start_matches('/').to_string();
                if !pat_clean.is_empty() {
                    patterns.push(GitPattern { negated: false, dir_only, anchored, pattern: pat_clean });
                }
                continue;
            } else if let Some(rest) = l.strip_prefix("\\#") {
                l = rest;
                let mut pat = format!("#{}", l);
                let mut dir_only = false;
                if pat.ends_with('/') { dir_only = true; pat = pat.trim_end_matches('/').to_string(); }
                let anchored = pat.contains('/');
                let pat_clean = pat.trim_start_matches('/').to_string();
                if !pat_clean.is_empty() {
                    patterns.push(GitPattern { negated: false, dir_only, anchored, pattern: pat_clean });
                }
                continue;
            }
            // Remove trailing spaces (not escaped). Simple: if ends with "\ " keep one space
            // We'll trim trailing spaces
            let mut owned = l.to_string();
            while owned.ends_with(' ') && !owned.ends_with("\\ ") {
                owned.pop();
            }
            // Replace "\ " with space (placeholder)
            owned = owned.replace("\\ ", " ");
            if owned.is_empty() { continue; }
            let mut dir_only = false;
            if owned.ends_with('/') {
                dir_only = true;
                while owned.ends_with('/') { owned.pop(); }
            }
            if owned.is_empty() { continue; }
            // anchored if contains slash (not counting trailing which removed)
            let anchored = owned.contains('/');
            let pat_clean = owned.trim_start_matches('/').to_string();
            if pat_clean.is_empty() { continue; }
            patterns.push(GitPattern { negated, dir_only, anchored, pattern: pat_clean });
        }
        Some(Self { patterns })
    }
    fn is_ignored(&self, rel: &Path, is_dir: bool) -> bool {
        if rel.as_os_str().is_empty() { return false; }
        let rel_str = rel.to_string_lossy().replace('\\', "/");
        let mut ignored = false;
        for pat in &self.patterns {
            if pat.dir_only && !is_dir { continue; }
            if matches_pattern(pat, &rel_str) {
                ignored = !pat.negated;
            }
        }
        ignored
    }
}

fn matches_pattern(pat: &GitPattern, rel: &str) -> bool {
    if pat.anchored {
        glob_path_match(&pat.pattern, rel)
    } else {
        // no slash (by definition anchored=false implies no slash in original except maybe?)
        // If pattern contains slash but anchored false shouldn't happen; fallback to basename
        // Match basename
        let base = rel.rsplit('/').next().unwrap_or(rel);
        // Pattern may be single segment
        if !pat.pattern.contains('/') {
            glob_segment_match(&pat.pattern, base)
        } else {
            // match any suffix of path segments
            // Try matching pattern against any suffix
            let parts: Vec<&str> = rel.split('/').collect();
            for i in 0..parts.len() {
                let suffix = parts[i..].join("/");
                if glob_path_match(&pat.pattern, &suffix) { return true; }
            }
            false
        }
    }
}

// Match a path (segments separated by /) against a glob path pattern
fn glob_path_match(pattern: &str, path: &str) -> bool {
    let pat_segs: Vec<&str> = pattern.split('/').collect();
    let path_segs: Vec<&str> = path.split('/').collect();
    glob_segs_match(&pat_segs, &path_segs)
}
fn glob_segs_match(pat: &[&str], path: &[&str]) -> bool {
    if pat.is_empty() {
        return path.is_empty();
    }
    if pat[0] == "**" {
        // ** matches zero or more segments
        // If ** is last, it matches everything remaining (including empty?)
        if pat.len() == 1 {
            return true;
        }
        for i in 0..=path.len() {
            if glob_segs_match(&pat[1..], &path[i..]) {
                return true;
            }
        }
        return false;
    }
    if path.is_empty() {
        return false;
    }
    if !glob_segment_match(pat[0], path[0]) {
        return false;
    }
    glob_segs_match(&pat[1..], &path[1..])
}

fn glob_segment_match(pattern: &str, text: &str) -> bool {
    // Convert to char vecs for unicode handling simplified to chars
    let p: Vec<char> = pattern.chars().collect();
    let t: Vec<char> = text.chars().collect();
    glob_segment_match_slice(&p, &t)
}
fn glob_segment_match_slice(p: &[char], t: &[char]) -> bool {
    if p.is_empty() {
        return t.is_empty();
    }
    match p[0] {
        '*' => {
            // * matches any sequence (including empty)
            for i in 0..=t.len() {
                if glob_segment_match_slice(&p[1..], &t[i..]) {
                    return true;
                }
            }
            false
        }
        '?' => {
            if t.is_empty() { false } else { glob_segment_match_slice(&p[1..], &t[1..]) }
        }
        '[' => {
            if t.is_empty() { return false; }
            // parse class
            let mut idx = 1usize;
            let mut negated = false;
            if idx < p.len() && (p[idx] == '!' || p[idx] == '^') {
                negated = true;
                idx += 1;
            }
            // leading ] is literal
            let mut matched = false;
            let c = t[0];
            let mut first = true;
            let mut prev: Option<char> = None;
            let mut closed = false;
            while idx < p.len() {
                if p[idx] == ']' && !first {
                    closed = true;
                    break;
                }
                first = false;
                if p[idx] == '\\' && idx + 1 < p.len() {
                    idx += 1;
                    if c == p[idx] { matched = true; }
                    prev = Some(p[idx]);
                    idx += 1;
                    continue;
                }
                if p[idx] == '-' && prev.is_some() && idx + 1 < p.len() && p[idx + 1] != ']' {
                    idx += 1;
                    let hi = if p[idx] == '\\' && idx + 1 < p.len() { idx += 1; p[idx] } else { p[idx] };
                    if let Some(lo) = prev {
                        if lo <= c && c <= hi { matched = true; }
                    }
                    prev = None;
                    idx += 1;
                    continue;
                }
                if c == p[idx] { matched = true; }
                prev = Some(p[idx]);
                idx += 1;
            }
            if !closed {
                // invalid pattern -> treat '[' literally
                if c == '[' {
                    return glob_segment_match_slice(&p[1..], &t[1..]);
                } else {
                    return false;
                }
            }
            if matched ^ negated {
                glob_segment_match_slice(&p[idx + 1..], &t[1..])
            } else {
                false
            }
        }
        '\\' => {
            if p.len() >= 2 {
                if !t.is_empty() && t[0] == p[1] {
                    glob_segment_match_slice(&p[2..], &t[1..])
                } else { false }
            } else {
                // trailing backslash literal
                if !t.is_empty() && t[0] == '\\' {
                    glob_segment_match_slice(&p[1..], &t[1..])
                } else { false }
            }
        }
        c => {
            if !t.is_empty() && t[0] == c {
                glob_segment_match_slice(&p[1..], &t[1..])
            } else { false }
        }
    }
}

// ---------- File copy helpers ----------
const FICLONE: libc::c_ulong = 0x40049409;

fn file_debug(f: &File) -> String {
    format!("{:?}", f)
}

fn copy_xattrs(src_file: &File, dest_file: &File, worker_tid: &str) {
    // List xattrs via flistxattr
    unsafe {
        let size = libc::flistxattr(src_file.as_raw_fd(), std::ptr::null_mut(), 0);
        if size <= 0 { 
            debug_as(worker_tid, "libfs::common", "Starting xattr copy...");
            return;
        }
    }
    // debug already printed by caller? caller prints Starting...
    // We'll be called after Starting debug; here enumerate
    let names = unsafe {
        let size = libc::flistxattr(src_file.as_raw_fd(), std::ptr::null_mut(), 0);
        if size <= 0 { return; }
        let mut buf = vec![0u8; size as usize];
        let ret = libc::flistxattr(src_file.as_raw_fd(), buf.as_mut_ptr() as *mut libc::c_char, buf.len());
        if ret < 0 { return; }
        buf.truncate(ret as usize);
        buf
    };
    // split by NUL
    let mut start = 0usize;
    for i in 0..names.len() {
        if names[i] == 0 {
            if i > start {
                let name_bytes = &names[start..i];
                if let Ok(name_str) = std::str::from_utf8(name_bytes) {
                    debug_as(worker_tid, "libfs::common", &format!("Copy xattr {:?}", name_str));
                    // get value
                    unsafe {
                        let cname = match std::ffi::CString::new(name_str) { Ok(c) => c, Err(_) => { start = i+1; continue; } };
                        let vsize = libc::fgetxattr(src_file.as_raw_fd(), cname.as_ptr(), std::ptr::null_mut(), 0);
                        if vsize >= 0 {
                            let mut vbuf = vec![0u8; vsize as usize];
                            let got = if vsize == 0 { 0 } else { libc::fgetxattr(src_file.as_raw_fd(), cname.as_ptr(), vbuf.as_mut_ptr() as *mut libc::c_void, vbuf.len()) };
                            if got >= 0 {
                                vbuf.truncate(got as usize);
                                let _ = libc::fsetxattr(dest_file.as_raw_fd(), cname.as_ptr(), vbuf.as_ptr() as *const libc::c_void, vbuf.len(), 0);
                            }
                        }
                    }
                }
            }
            start = i + 1;
        }
    }
}

use std::os::unix::io::AsRawFd;

fn copy_metadata(
    src_file: &File,
    dest_file: &File,
    src_meta: &fs::Metadata,
    config: &Config,
    worker_tid: &str,
) -> Result<(), io::Error> {
    if !config.no_perms {
        debug_as(worker_tid, "libfs::common", "Starting xattr copy...");
        copy_xattrs(src_file, dest_file, worker_tid);
        debug_as(worker_tid, "libfs::common", "Performing permissions copy");
        let mode = src_meta.permissions().mode();
        dest_file.set_permissions(fs::Permissions::from_mode(mode))?;
    }
    if config.ownership {
        let uid = src_meta.uid();
        let gid = src_meta.gid();
        let ret = unsafe { libc::fchown(dest_file.as_raw_fd(), uid, gid) };
        if ret != 0 {
            warn(&format!("Failed to copy file ownership: {}", file_debug(src_file)));
        }
    }
    if !config.no_timestamps {
        debug_as(worker_tid, "libfs::common", "Performing timestamp copy");
        let atime = src_meta.atime();
        let atime_nsec = src_meta.atime_nsec();
        let mtime = src_meta.mtime();
        let mtime_nsec = src_meta.mtime_nsec();
        let times: [libc::timespec; 2] = [
            libc::timespec { tv_sec: atime as libc::time_t, tv_nsec: atime_nsec as libc::c_long },
            libc::timespec { tv_sec: mtime as libc::time_t, tv_nsec: mtime_nsec as libc::c_long },
        ];
        let ret = unsafe { libc::futimens(dest_file.as_raw_fd(), times.as_ptr()) };
        if ret != 0 {
            return Err(io::Error::last_os_error());
        }
    }
    Ok(())
}

fn existing_backups_max(dest: &Path) -> Option<u64> {
    let parent = match dest.parent() {
        Some(p) if !p.as_os_str().is_empty() => p.to_path_buf(),
        _ => PathBuf::from("."),
    };
    let file_name = dest.file_name()?.to_string_lossy().to_string();
    let prefix = format!("{}.~", file_name);
    let entries = fs::read_dir(&parent).ok()?;
    let mut max: Option<u64> = None;
    for e in entries.flatten() {
        let name = e.file_name().to_string_lossy().to_string();
        if let Some(rest) = name.strip_prefix(&prefix) {
            if let Some(num_str) = rest.strip_suffix('~') {
                if !num_str.is_empty() && num_str.chars().all(|c| c.is_ascii_digit()) {
                    if let Ok(n) = num_str.parse::<u64>() {
                        max = Some(match max { Some(m) => m.max(n), None => n });
                    }
                }
            }
        }
    }
    max
}

fn do_backup(dest: &Path, config: &Config) -> Result<bool, io::Error> {
    if config.backup == BackupMode::None {
        return Ok(false);
    }
    if !dest.exists() {
        return Ok(false);
    }
    let max = existing_backups_max(dest);
    let next: u64 = match config.backup {
        BackupMode::Numbered => max.map(|m| m + 1).unwrap_or(1),
        BackupMode::Auto => {
            match max {
                Some(m) => m + 1,
                None => return Ok(false),
            }
        }
        BackupMode::None => return Ok(false),
    };
    let mut backup_os = dest.as_os_str().to_owned();
    backup_os.push(format!(".~{}~", next));
    let backup_path = PathBuf::from(backup_os);
    info(&format!("Backup: Rename {:?} to {:?}", dest, backup_path));
    fs::rename(dest, &backup_path)?;
    Ok(true)
}

// Data copy with reflink handling. Returns Ok(true) if reflinked.
fn copy_file_data(
    src_file: &File,
    dest_file: &File,
    size: u64,
    config: &Config,
    progress: &Arc<Progress>,
    worker_tid: &str,
    driver: Driver,
) -> Result<bool, AppError> {
    // Reflink attempt
    if config.reflink != ReflinkMode::Never {
        debug_as(worker_tid, "libxcp::operations", &format!("Attempting reflink from {}->{}", file_debug(src_file), file_debug(dest_file)));
        let ret = unsafe { libc::ioctl(dest_file.as_raw_fd(), FICLONE, src_file.as_raw_fd()) };
        if ret == 0 {
            debug_as(worker_tid, "libxcp::operations", &format!("Reflink {} succeeded", file_debug(dest_file)));
            progress.inc(size);
            return Ok(true);
        } else {
            if config.reflink == ReflinkMode::Always {
                let msg = format!("Failed to reflink file and 'always' was specified: {}->{}", file_debug(src_file), file_debug(dest_file));
                return Err(AppError::DuringCopy(msg));
            } else {
                debug_as(worker_tid, "libxcp::operations", "Failed to reflink, falling back to copy");
                // fall through
            }
        }
    }
    // Block size 0 panic simulation
    if config.block_size == 0 {
        match driver {
            Driver::Parfile => {
                if size > 0 {
                    let tid = unsafe { libc::syscall(libc::SYS_gettid) };
                    eprintln!("\nthread '<unnamed>' ({}) panicked at libxcp/src/feedback.rs:98:16:", tid);
                    eprintln!("attempt to divide by zero");
                    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                    return Err(AppError::ErrorDuringCopyOperation);
                } else {
                    return Ok(false);
                }
            }
            Driver::Parblock => {
                let tid = unsafe { libc::syscall(libc::SYS_gettid) };
                eprintln!("\nthread '<unnamed>' ({}) panicked at libxcp/src/drivers/parblock.rs:121:18:", tid);
                eprintln!("attempt to divide by zero");
                eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                return Err(AppError::ErrorDispatchingCopyOperation);
            }
        }
    }
    // Sparse-aware copy using copy_file_range
    copy_sparse(src_file, dest_file, size, config, progress).map_err(|e| AppError::DuringCopy(e.to_string()))?;
    Ok(false)
}

fn copy_sparse(src_file: &File, dest_file: &File, size: u64, config: &Config, progress: &Arc<Progress>) -> Result<(), io::Error> {
    if size == 0 { return Ok(()); }
    let src_fd = src_file.as_raw_fd();
    let dest_fd = dest_file.as_raw_fd();
    let mut offset: i64 = 0;
    let size_i = size as i64;
    // Try SEEK_DATA; if fails with EINVAL, treat whole file as data
    loop {
        if offset >= size_i { break; }
        let data_start = unsafe { libc::lseek(src_fd, offset as libc::off_t, libc::SEEK_DATA) };
        if data_start < 0 {
            let err = io::Error::last_os_error();
            match err.raw_os_error() {
                Some(libc::ENXIO) => break, // no more data
                Some(libc::EINVAL) => {
                    // No sparse support: copy rest as data
                    copy_range_extent(src_file, dest_file, offset, size_i, config, progress)?;
                    break;
                }
                _ => {
                    // Fallback: copy as normal extent
                    copy_range_extent(src_file, dest_file, offset, size_i, config, progress)?;
                    break;
                }
            }
        }
        let hole_start = unsafe { libc::lseek(src_fd, data_start as libc::off_t, libc::SEEK_HOLE) };
        let extent_end = if hole_start < 0 { size_i } else { hole_start.min(size_i as libc::off_t) as i64 };
        if extent_end > data_start as i64 {
            copy_range_extent(src_file, dest_file, data_start as i64, extent_end, config, progress)?;
        }
        offset = extent_end;
        if hole_start < 0 { break; }
    }
    Ok(())
}

fn copy_range_extent(src_file: &File, dest_file: &File, start: i64, end: i64, config: &Config, progress: &Arc<Progress>) -> Result<(), io::Error> {
    let src_fd = src_file.as_raw_fd();
    let dest_fd = dest_file.as_raw_fd();
    let mut in_off: i64 = start;
    let mut out_off: i64 = start;
    while in_off < end {
        let remaining = (end - in_off) as u64;
        let chunk = remaining.min(config.block_size.max(1));
        // cap chunk to something reasonable for copy_file_range (2GB-1)
        let chunk_capped = chunk.min(0x7fff_f000u64);
        let mut in_ptr: libc::loff_t = in_off as libc::loff_t;
        let mut out_ptr: libc::loff_t = out_off as libc::loff_t;
        let ret = unsafe { libc::copy_file_range(src_fd, &mut in_ptr, dest_fd, &mut out_ptr, chunk_capped as usize, 0) };
        if ret < 0 {
            let err = io::Error::last_os_error();
            // For files where copy_file_range is not usable we might try buffered fallback
            // except when the error indicates same-file etc. Original returned error for same-file (EINVAL).
            // Determine: if error is EINVAL, propagate (matches observed same-file)
            // For other errors, fall back to buffered copy for remaining extent
            match err.raw_os_error() {
                Some(libc::EINVAL) => return Err(err),
                _ => {
                    // buffered fallback
                    return copy_buffered_extent(src_file, dest_file, in_off, end, config, progress);
                }
            }
        }
        if ret == 0 {
            // EOF
            break;
        }
        in_off += ret as i64;
        out_off += ret as i64;
        progress.inc(ret as u64);
    }
    Ok(())
}

fn copy_buffered_extent(src_file: &File, dest_file: &File, start: i64, end: i64, config: &Config, progress: &Arc<Progress>) -> Result<(), io::Error> {
    // Use pread/pwrite
    let src_fd = src_file.as_raw_fd();
    let dest_fd = dest_file.as_raw_fd();
    let buf_size = config.block_size.min(1024 * 1024).max(1) as usize;
    let mut buf = vec![0u8; buf_size];
    let mut off = start;
    while off < end {
        let to_read = ((end - off) as usize).min(buf.len());
        let ret = unsafe { libc::pread(src_fd, buf.as_mut_ptr() as *mut libc::c_void, to_read, off as libc::off_t) };
        if ret < 0 { return Err(io::Error::last_os_error()); }
        if ret == 0 { break; }
        let mut written = 0usize;
        while written < ret as usize {
            let w = unsafe { libc::pwrite(dest_fd, buf[written..].as_ptr() as *const libc::c_void, (ret as usize - written), (off + written as i64) as libc::off_t) };
            if w < 0 { return Err(io::Error::last_os_error()); }
            written += w as usize;
        }
        progress.inc(ret as u64);
        off += ret as i64;
    }
    Ok(())
}

// Copy a regular file.
// worker_tid is the logical tid string (numeric) for debugging and display
// Returns Ok(reflinked?) or AppError which is already categorized
// The caller is responsible for logging "Error copying..." etc for DuringCopy errors etc,
// but for reflink=always and copy_range errors those are DuringCopy.
// For open errors, those are also DuringCopy with io string.
// For AppError::ErrorDuringCopyOperation etc, caller should not log extra.
fn copy_regular_file(src: &Path, dest: &Path, config: &Config, progress: &Arc<Progress>, worker_tid: &str) -> Result<bool, AppError> {
    // open source
    let src_file = File::open(src).map_err(|e| AppError::DuringCopy(e.to_string()))?;
    let src_meta = src_file.metadata().map_err(|e| AppError::DuringCopy(e.to_string()))?;
    let size = src_meta.len();
    // backup (inside copy operation, after source opened)
    // backup errors are treated as copy errors (io)
    if let Err(e) = do_backup(dest, config) {
        return Err(AppError::DuringCopy(e.to_string()));
    }
    // open dest
    let dest_file = OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(dest)
        .map_err(|e| AppError::DuringCopy(e.to_string()))?;
    // set length (preallocate)
    dest_file.set_len(size).map_err(|e| AppError::DuringCopy(e.to_string()))?;

    // data
    let data_result = copy_file_data(&src_file, &dest_file, size, config, progress, worker_tid, config.driver);

    // if data_result is the special blocksize-0 panic, original worker panics, metadata not run
    if let Err(e) = &data_result {
        if matches!(e, AppError::ErrorDuringCopyOperation | AppError::ErrorDispatchingCopyOperation) {
            return Err(AppError::DuringCopy("dummy".to_string())); // placeholder, re-mapped below
        }
    }
    // Actually preserve special errors:
    let data_result = match data_result {
        Ok(v) => Ok(v),
        Err(AppError::ErrorDuringCopyOperation) => return Err(AppError::ErrorDuringCopyOperation),
        Err(AppError::ErrorDispatchingCopyOperation) => return Err(AppError::ErrorDispatchingCopyOperation),
        Err(e) => Err(e),
    };

    // metadata (run even if data failed, as original)
    let meta_result = copy_metadata(&src_file, &dest_file, &src_meta, config, worker_tid);

    // fsync
    let mut fsync_result: Result<(), io::Error> = Ok(());
    if config.fsync {
        debug_as(worker_tid, "libxcp::operations", &format!("Syncing file {}", file_debug(&dest_file)));
        fsync_result = dest_file.sync_all();
    }

    match data_result {
        Ok(reflinked) => {
            if let Err(e) = meta_result {
                return Err(AppError::DuringCopy(e.to_string()));
            }
            if let Err(e) = fsync_result {
                return Err(AppError::DuringCopy(e.to_string()));
            }
            Ok(reflinked)
        }
        Err(e) => Err(e),
    }
}

fn copy_special_file(src: &Path, dest: &Path, _config: &Config) -> Result<(), AppError> {
    // metadata via symlink_metadata (source may be... walker ensures special, not symlink unless -L canonical)
    let meta = fs::metadata(src).map_err(|e| AppError::Io(e))?;
    // alternative use symlink_metadata if src is special itself; metadata follows but special has no link
    let mode = meta.mode();
    let rdev = meta.rdev();
    if dest.exists() {
        fs::remove_file(dest).map_err(|e| AppError::Io(e))?;
    }
    // mknod
    let cpath = match std::ffi::CString::new(dest.as_os_str().as_bytes()) {
        Ok(c) => c,
        Err(_) => return Err(AppError::Io(io::Error::new(io::ErrorKind::InvalidInput, "invalid path"))),
    };
    let ret = unsafe { libc::mknod(cpath.as_ptr(), mode as libc::mode_t, rdev as libc::dev_t) };
    if ret != 0 {
        return Err(AppError::Io(io::Error::last_os_error()));
    }
    Ok(())
}

fn copy_link(target: &Path, dest: &Path) -> Result<(), io::Error> {
    std::os::unix::fs::symlink(target, dest)
}

// ---------- Main run ----------
fn main() -> ExitCode {
    let matches = build_cli().get_matches();

    let verbose_count = matches.get_count("verbose");
    VERBOSITY.store(verbose_count.min(255) as u8, Ordering::SeqCst);

    let recursive = matches.get_flag("recursive");
    let dereference = matches.get_flag("dereference");
    let workers_raw = *matches.get_one::<usize>("workers").unwrap_or(&4);
    let block_size = *matches.get_one::<u64>("block-size").unwrap_or(&1_000_000);
    let no_clobber = matches.get_flag("no-clobber");
    let force = matches.get_flag("force");
    let gitignore_flag = matches.get_flag("gitignore");
    let glob_flag = matches.get_flag("glob");
    let no_progress = matches.get_flag("no-progress");
    let no_perms = matches.get_flag("no-perms");
    let no_timestamps = matches.get_flag("no-timestamps");
    let ownership = matches.get_flag("ownership");
    let driver = *matches.get_one::<Driver>("driver").unwrap();
    let no_target_directory = matches.get_flag("no-target-directory");
    let target_directory_str: Option<String> = matches.get_one::<String>("target-directory").cloned();
    let fsync_flag = matches.get_flag("fsync");
    let reflink_mode = *matches.get_one::<ReflinkMode>("reflink").unwrap();
    let backup_mode = *matches.get_one::<BackupMode>("backup").unwrap();

    let paths: Vec<String> = matches
        .get_many::<String>("PATHS")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    let config = Config {
        recursive,
        dereference,
        workers: workers_raw,
        block_size,
        no_clobber,
        force,
        gitignore: gitignore_flag,
        glob_expand: glob_flag,
        no_progress,
        no_perms,
        no_timestamps,
        ownership,
        driver,
        no_target_directory,
        target_directory: target_directory_str.clone().map(PathBuf::from),
        fsync: fsync_flag,
        reflink: reflink_mode,
        backup: backup_mode,
    };

    // WARN for reflink never appears before other validation
    if config.reflink == ReflinkMode::Never {
        warn("--reflink=never is selected, however the Linux kernel may override this.");
    }

    match run(&config, paths) {
        Ok(()) => {
            info("Copy complete");
            ExitCode::from(0)
        }
        Err(e) => {
            // Progress clear on error if it was drawn handled inside run? We'll handle global? progress is inside run.
            // For errors that are copy errors, Received log already printed inside run.
            print_final_error(&e);
            ExitCode::from(1)
        }
    }
}

fn run(config: &Config, paths: Vec<String>) -> Result<(), AppError> {
    // force / no-clobber conflict first
    if config.force && config.no_clobber {
        return Err(AppError::Msg("Invalid arguments: --force and --noclobber cannot be set at the same time.".to_string()));
    }

    let target_dir_opt = &config.target_directory;

    // Insufficient arguments check
    if paths.is_empty() && target_dir_opt.is_none() {
        return Err(AppError::Msg("Invalid arguments: Insufficient arguments".to_string()));
    }

    // split sources / dest
    let (sources_raw, dest): (Vec<PathBuf>, PathBuf) = if let Some(td) = target_dir_opt {
        (paths.iter().map(PathBuf::from).collect(), td.clone())
    } else {
        // paths non-empty here (if empty we returned, or td present)
        if paths.is_empty() {
            (Vec::new(), PathBuf::new())
        } else {
            let mut p: Vec<PathBuf> = paths.iter().map(PathBuf::from).collect();
            let d = p.pop().unwrap();
            (p, d)
        }
    };

    // Glob expansion
    let mut sources: Vec<PathBuf> = Vec::new();
    if config.glob_expand {
        for pat in &sources_raw {
            let pat_str = pat.to_string_lossy().to_string();
            match glob::glob(&pat_str) {
                Ok(paths_iter) => {
                    for entry in paths_iter {
                        match entry {
                            Ok(p) => sources.push(p),
                            Err(e) => return Err(AppError::Msg(e.to_string())),
                        }
                    }
                }
                Err(e) => {
                    return Err(AppError::Msg(e.to_string()));
                }
            }
        }
    } else {
        sources = sources_raw;
    }

    if sources.is_empty() {
        return Err(AppError::Msg("Invalid source: No source files found.".to_string()));
    }

    if sources.len() > 1 && !dest.is_dir() {
        return Err(AppError::Msg("Invalid destination: Multiple sources and destination is not a directory.".to_string()));
    }

    // Validate each source (logging Copying source before each check as original)
    for source in &sources {
        info(&format!("Copying source {:?} to {:?}", source, dest));
        if !source.exists() {
            return Err(AppError::Msg("Invalid source: Source does not exist.".to_string()));
        }
        if source.is_dir() && dest.is_file() {
            return Err(AppError::Msg("Invalid destination: Cannot copy a directory to a file.".to_string()));
        }
        if source.is_dir() && !config.recursive {
            return Err(AppError::Msg("Invalid source: Source is directory and --recursive not specified.".to_string()));
        }
        if source == &dest {
            return Err(AppError::Msg("Invalid source: Cannot copy a directory into itself".to_string()));
        }
    }

    // Progress setup: enabled if not no-progress and stderr is a tty
    let stderr_is_tty = unsafe { libc::isatty(libc::STDERR_FILENO) != 0 };
    let progress_enabled = !config.no_progress && stderr_is_tty;
    let progress = Arc::new(Progress::new(progress_enabled));

    // Execute copy
    let result = execute_copy(config, &sources, &dest, &progress);

    match result {
        Ok(()) => {
            progress.finish();
            Ok(())
        }
        Err(e) => {
            // Received error log for certain categories (already potentially handled per-operation)
            // We centralized: execute_copy already logged Received / Error copying etc for ops it handled.
            // For errors returned directly from execute_copy that are copy/destination errors, we need Received log if not already logged.
            // Approach: execute_copy logs Received before returning those errors, so here just clear progress.
            progress.clear();
            Err(e)
        }
    }
}

fn target_base_for(source: &Path, dest: &Path, config: &Config) -> PathBuf {
    if dest.is_dir() && !config.no_target_directory {
        if let Some(fname) = source.file_name() {
            dest.join(fname)
        } else {
            dest.to_path_buf()
        }
    } else {
        dest.to_path_buf()
    }
}

fn execute_copy(config: &Config, sources: &[PathBuf], dest: &Path, progress: &Arc<Progress>) -> Result<(), AppError> {
    // Resolve workers for debug output (not actually used for threads in sequential design)
    let _workers_resolved = if config.workers == 0 {
        std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
    } else {
        config.workers
    };

    // Debug: emulate workers startup for parfile
    // We will emit them lazily in driver-specific places to roughly mirror original,
    // but debug logs are order-nondeterministic in original, so we emit a few here.
    // To avoid excessive divergence, emit startup logs at -vv for parfile only before walking.
    let walker_tid = match config.driver {
        Driver::Parfile => "3",
        Driver::Parblock => "4",
    };
    let worker_tid = match config.driver {
        Driver::Parfile => "4",
        Driver::Parblock => "3", // dispatcher
    };

    if config.driver == Driver::Parfile && verbosity() >= 2 {
        // Note: original emits these from actual worker threads interleaved; order differs per run.
        // Emit worker startup logs (resolved count, capped display? emit all)
        // For very large workers, emitting many logs would differ but original would also have many threads.
        let count = _workers_resolved.min(1024);
        for i in 0..count {
            let tid = (4 + i).to_string();
            debug_as(&tid, "libxcp::drivers::parfile", &format!("Starting copy worker ThreadId({})", tid));
        }
    }

    // For each source, walk
    for source in sources {
        let res = walk_and_copy_source(config, source, dest, progress, walker_tid, worker_tid);
        if let Err(e) = res {
            // Check if error needs Received log
            // Categories:
            // - DuringCopy: already logged Error copying / Dispatcher etc inside copy operation, and Received should be printed here if not already?
            // Our per-op handling logs both Error copying and creates error; we will log Received here for DuringCopy and DestinationExists, except special block-size errors which have no Received.
            match &e {
                AppError::DuringCopy(_) => {
                    log_error(&format!("Received error: {}", e));
                }
                AppError::DestinationExists(_) => {
                    log_error(&format!("Received error: {}", e));
                }
                _ => {}
            }
            // parblock queuing logs on some errors? For parblock, if error occurs during dispatch, original might still not print Queuing complete in file-copy error cases (it prints Dispatch log, then error). For no-clobber, it printed Queuing/Pool complete before Received. Hmm.
            // Handling for parblock completion logs on success/error is done inside walk for success path; for error we mimic earlier: if driver is parblock and error is DestinationExists, Queuing/Pool logs are INFO already needed before Received.
            // Since INFO logs are stdout and Received stderr they are separate streams, order across streams not crucial.
            // If parblock and DestinationExists, we emit Queuing/Pool here before returning (INFO)
            if config.driver == Driver::Parblock {
                // For DestinationExists case, original printed Queuing complete / Pool complete (INFO)
                if matches!(e, AppError::DestinationExists(_)) {
                    info("Queuing complete");
                    info("Pool complete");
                }
            }
            // shutdown workers debug
            if config.driver == Driver::Parfile && verbosity() >= 2 {
                let count = _workers_resolved.min(1024);
                for i in 0..count {
                    let tid = (4 + i).to_string();
                    debug_as(&tid, "libxcp::drivers::parfile", &format!("Copy worker ThreadId({}) shutting down", tid));
                }
            }
            return Err(e);
        }
    }

    // Success completion per driver
    if config.driver == Driver::Parfile && verbosity() >= 2 {
        let count = _workers_resolved.min(1024);
        for i in 0..count {
            let tid = (4 + i).to_string();
            debug_as(&tid, "libxcp::drivers::parfile", &format!("Copy worker ThreadId({}) shutting down", tid));
        }
    }
    if config.driver == Driver::Parblock {
        info("Queuing complete");
        info("Pool complete");
    }
    Ok(())
}

fn walk_and_copy_source(
    config: &Config,
    source: &Path,
    dest: &Path,
    progress: &Arc<Progress>,
    walker_tid: &str,
    worker_tid: &str,
) -> Result<(), AppError> {
    let target_base = target_base_for(source, dest, config);
    debug_as(walker_tid, "libxcp::operations", &format!("Starting walk worker ThreadId({})", walker_tid));
    debug_as(walker_tid, "libxcp::operations", &format!("Target base is {:?}", target_base));

    // Gitignore loading
    let gitignore: Option<Gitignore> = if config.gitignore {
        // only if source is directory (following)
        let is_dir_source = source.is_dir();
        if is_dir_source {
            let gi_path = source.join(".gitignore");
            if gi_path.is_file() || gi_path.exists() {
                info(&format!("Using .gitignore file {:?}", gi_path));
                debug_as(walker_tid, "ignore::gitignore", &format!("opened gitignore file: {}", gi_path.display()));
                Gitignore::load(&gi_path)
            } else {
                None
            }
        } else {
            None
        }
    } else {
        None
    };

    // Build walker
    let walker = WalkDir::new(source);
    // WalkDir iterator: use into_iter, with filter_entry if gitignore present
    // We need to handle filter manually to keep debug Got entry behaviour: ignored entries are not logged as Got.
    // filter_entry in walkdir will suppress them entirely.
    let mut iter: Box<dyn Iterator<Item = Result<walkdir::DirEntry, walkdir::Error>>> = if let Some(gi) = &gitignore {
        // Clone patterns for closure: we need to move gitignore check into closure; we keep a reference via Arc
        // Instead, we handle filtering manually in loop using gi (below) and not use filter_entry.
        // But to replicate that ignored dirs are not descended, manual handling must tell WalkDir not to descend.
        // WalkDir iterator doesn't provide skip_current_dir without filter_entry/iterator API.
        // The iterator returned by WalkDir has method `skip_current_dir` when using `Iter` directly (not boxed iterator for loop)
        // So we will handle loop manually below rather than this boxed iter.
        let _ = gi;
        Box::new(walker.into_iter())
    } else {
        Box::new(walker.into_iter())
    };

    // Manual loop using the WalkDir iterator type directly would be easier,
    // but we have boxed iterator; we can still handle ignored dirs by noting that
    // WalkDir will descend unless we use its Iter API. To achieve descent control,
    // we re-implement using direct WalkDir Iter below in a second pass if gitignore present?
    // Simplify: if gitignore is present, we use WalkDir's into_iter().filter_entry via rebuilding iterator
    // For this function's control flow, we will branch:
    if let Some(gi) = &gitignore {
        // Rebuild walker with filter
        let source_clone = source.to_path_buf();
        let gi_patterns = gi.patterns.clone();
        // We need to capture source for relative calculations in filter
        let walker2 = WalkDir::new(source);
        let filtered = walker2.into_iter().filter_entry(move |entry| {
            // Root entry: always keep
            if entry.depth() == 0 {
                return true;
            }
            let rel = match entry.path().strip_prefix(&source_clone) {
                Ok(r) => r.to_path_buf(),
                Err(_) => return true,
            };
            let is_dir = entry.file_type().is_dir();
            // Build a temporary Gitignore view
            let tmp = Gitignore { patterns: gi_patterns.clone() };
            !tmp.is_ignored(&rel, is_dir)
        });
        for entry_res in filtered {
            debug_as(walker_tid, "libxcp::operations", &format!("Got tree entry {:?}", entry_res));
            let entry = match entry_res {
                Ok(e) => e,
                Err(e) => return Err(AppError::Walkdir(e)),
            };
            // Process entry (note: root depth gitignore not filtered)
            process_entry(config, source, &target_base, entry.path(), entry.file_type(), progress, walker_tid, worker_tid, true)?;
        }
        debug_as(walker_tid, "libxcp::operations", &format!("Walk-worker finished: ThreadId({})", walker_tid));
        return Ok(());
    }

    // No gitignore path
    for entry_res in &mut iter {
        debug_as(walker_tid, "libxcp::operations", &format!("Got tree entry {:?}", entry_res));
        let entry = match entry_res {
            Ok(e) => e,
            Err(e) => return Err(AppError::Walkdir(e)),
        };
        process_entry(config, source, &target_base, entry.path(), entry.file_type(), progress, walker_tid, worker_tid, false)?;
    }
    debug_as(walker_tid, "libxcp::operations", &format!("Walk-worker finished: ThreadId({})", walker_tid));
    Ok(())
}

// Need Clone for GitPattern for filter closure
// (derive already? we added Clone above)

fn process_entry(
    config: &Config,
    source_root: &Path,
    target_base: &Path,
    entry_path: &Path,
    entry_file_type: &fs::FileType,
    progress: &Arc<Progress>,
    walker_tid: &str,
    worker_tid: &str,
    _from_gitignore: bool,
) -> Result<(), AppError> {
    // Compute destination for this entry
    let dest_path: PathBuf = if entry_path == source_root {
        target_base.to_path_buf()
    } else {
        match entry_path.strip_prefix(source_root) {
            Ok(rel) => target_base.join(rel),
            Err(_) => {
                // Fallback: if entry path has different prefix due to ./ etc, use file_name join
                // WalkDir yields paths starting with source_root as given, so strip should work.
                target_base.to_path_buf()
            }
        }
    };

    // Dereference handling
    let (effective_path, effective_file_type_is_dir, effective_is_file, effective_is_symlink, effective_is_special) = if config.dereference {
        let canon = fs::canonicalize(entry_path).map_err(|e| AppError::Io(e))?;
        debug_as(walker_tid, "libxcp::operations", &format!("Dereferencing {:?} into {:?}", entry_path, canon));
        let meta = fs::metadata(&canon).map_err(|e| AppError::Io(e))?;
        let ft = meta.file_type();
        (canon, ft.is_dir(), ft.is_file(), ft.is_symlink(), !ft.is_dir() && !ft.is_file() && !ft.is_symlink())
    } else {
        let is_dir = entry_file_type.is_dir();
        let is_file = entry_file_type.is_file();
        let is_link = entry_file_type.is_symlink();
        (entry_path.to_path_buf(), is_dir, is_file, is_link, !is_dir && !is_file && !is_link)
    };

    if effective_file_type_is_dir {
        // Directory creation
        debug_as(walker_tid, "libxcp::operations", &format!("Creating target directory {:?}", dest_path));
        if config.no_clobber && dest_path.exists() {
            return Err(AppError::DestinationExists(dest_path.clone()));
        }
        // Note: create_dir_all on existing dir succeeds; on existing file returns error
        // Original used create_dir_all? It returned "Error creating target directory: File exists" for dest-is-file case.
        // create_dir_all on existing file: std returns error? It checks is_dir... It may return Ok if path is_dir else create_dir fails.
        // To match, we attempt create_dir_all and map error.
        // However create_dir_all on an existing directory symlink etc returns Ok.
        if let Err(e) = fs::create_dir_all(&dest_path) {
            log_error(&format!("Error creating target directory: {}", e));
            return Err(AppError::DirCreate(e));
        }
        return Ok(());
    }

    // Non-directory: no-clobber check in walker before sending operation
    if config.no_clobber && dest_path.exists() {
        return Err(AppError::DestinationExists(dest_path.clone()));
    }

    if effective_is_symlink {
        // read link target
        let target = fs::read_link(entry_path).map_err(|e| AppError::Io(e))?;
        debug_as(walker_tid, "libxcp::operations", &format!("Send symlink operation {:?} to {:?}", target, dest_path));
        // Execute link operation
        match config.driver {
            Driver::Parfile => {
                if verbosity() >= 2 {
                    debug_as(worker_tid, "libxcp::drivers::parfile", &format!("Received operation Link({:?}, {:?})", target, dest_path));
                }
                info(&format!("Worker[{}]: Symlink {:?} -> {:?}", tid_debug(), target, dest_path));
                // Parfile ignores link errors
                let _ = copy_link(&target, &dest_path);
                Ok(())
            }
            Driver::Parblock => {
                info(&format!("Dispatch[{}]: Symlink {:?} -> {:?}", tid_debug(), target, dest_path));
                match copy_link(&target, &dest_path) {
                    Ok(()) => Ok(()),
                    Err(e) => {
                        log_error(&format!("Error symlinking: {:?} -> {:?}; aborting.", target, dest_path));
                        Err(AppError::DuringCopy(e.to_string()))
                    }
                }
            }
        }
    } else if effective_is_file {
        // Add to progress total
        // Size from effective path metadata
        let size = fs::metadata(&effective_path).map(|m| m.len()).unwrap_or(0);
        progress.add_total(size);
        debug_as(walker_tid, "libxcp::operations", &format!("Send copy operation {:?} to {:?}", effective_path, dest_path));
        // Execute copy
        match config.driver {
            Driver::Parfile => {
                if verbosity() >= 2 {
                    debug_as(worker_tid, "libxcp::drivers::parfile", &format!("Received operation Copy({:?}, {:?})", effective_path, dest_path));
                }
                info(&format!("Worker[{}]: Copy {:?} -> {:?}", tid_debug(), effective_path, dest_path));
                // copy_regular_file uses worker_tid param for debug (libfs etc). Use worker_tid numeric? Our worker_tid is "4" for parfile.
                match copy_regular_file(&effective_path, &dest_path, config, progress, worker_tid) {
                    Ok(_reflinked) => Ok(()),
                    Err(AppError::ErrorDuringCopyOperation) => Err(AppError::ErrorDuringCopyOperation),
                    Err(AppError::ErrorDispatchingCopyOperation) => Err(AppError::ErrorDispatchingCopyOperation),
                    Err(e) => {
                        // Log Error copying for DuringCopy errors
                        if let AppError::DuringCopy(_) = e {
                            log_error(&format!("Error copying: {:?} -> {:?}; aborting.", effective_path, dest_path));
                        }
                        Err(e)
                    }
                }
            }
            Driver::Parblock => {
                info(&format!("Dispatch[{}]: Copy {:?} -> {:?}", tid_debug(), effective_path, dest_path));
                match copy_regular_file(&effective_path, &dest_path, config, progress, worker_tid) {
                    Ok(reflinked) => {
                        if reflinked {
                            info("Reflinked, skipping rest of copy");
                        }
                        Ok(())
                    }
                    Err(AppError::ErrorDuringCopyOperation) => Err(AppError::ErrorDuringCopyOperation),
                    Err(AppError::ErrorDispatchingCopyOperation) => Err(AppError::ErrorDispatchingCopyOperation),
                    Err(e) => {
                        if let AppError::DuringCopy(_) = e {
                            log_error(&format!("Dispatcher: Error copying {:?} -> {:?}.", effective_path, dest_path));
                        }
                        Err(e)
                    }
                }
            }
        }
    } else if effective_is_special {
        debug_as(walker_tid, "libxcp::operations", &format!("Special file found: {:?} to {:?}", entry_path, dest_path));
        // log send? Original debug for special: "Special file found: ..." (not Send)
        match config.driver {
            Driver::Parfile => {
                if verbosity() >= 2 {
                    debug_as(worker_tid, "libxcp::drivers::parfile", &format!("Received operation Special({:?}, {:?})", entry_path, dest_path));
                }
                info(&format!("Worker[{}]: Special file {:?} -> {:?}", tid_debug(), entry_path, dest_path));
                copy_special_file(&effective_path, &dest_path, config)
            }
            Driver::Parblock => {
                info(&format!("Dispatch[{}]: Special file {:?} -> {:?}", tid_debug(), entry_path, dest_path));
                copy_special_file(&effective_path, &dest_path, config)
            }
        }
    } else {
        // Unknown (should be special)
        Ok(())
    }
}
RS
"}

