new='''fn copy_xattrs(src: &Path, dest: &Path, worker_tid: &str) {
    // Use path-based xattr syscalls, as the original (xattr crate) does; this
    // also yields the same listing order as listxattr (security.* first).
    let src_c = match std::ffi::CString::new(src.as_os_str().as_bytes()) { Ok(c) => c, Err(_) => return };
    let dest_c = match std::ffi::CString::new(dest.as_os_str().as_bytes()) { Ok(c) => c, Err(_) => return };
    let names = unsafe {
        let size = libc::listxattr(src_c.as_ptr(), std::ptr::null_mut(), 0);
        if size <= 0 { return; }
        let mut buf = vec![0u8; size as usize];
        let ret = libc::listxattr(src_c.as_ptr(), buf.as_mut_ptr() as *mut libc::c_char, buf.len());
        if ret < 0 { return; }
        buf.truncate(ret as usize);
        buf
    };
    let mut start = 0usize;
    for i in 0..names.len() {
        if names[i] == 0 {
            if i > start {
                let name_bytes = &names[start..i];
                if let Ok(name_str) = std::str::from_utf8(name_bytes) {
                    debug_as(worker_tid, "libfs::common", &format!("Copy xattr {:?}", name_str));
                    unsafe {
                        let cname = match std::ffi::CString::new(name_str) { Ok(c) => c, Err(_) => { start = i+1; continue; } };
                        let vsize = libc::getxattr(src_c.as_ptr(), cname.as_ptr(), std::ptr::null_mut(), 0);
                        if vsize >= 0 {
                            let mut vbuf = vec![0u8; vsize as usize];
                            let got = if vsize == 0 { 0 } else { libc::getxattr(src_c.as_ptr(), cname.as_ptr(), vbuf.as_mut_ptr() as *mut libc::c_void, vbuf.len()) };
                            if got >= 0 {
                                vbuf.truncate(got as usize);
                                let _ = libc::setxattr(dest_c.as_ptr(), cname.as_ptr(), vbuf.as_ptr() as *const libc::c_void, vbuf.len(), 0);
                            }
                        }
                    }
                }
            }
            start = i + 1;
        }
    }
}
'''
