fn env_bytes(name: &str) -> Option<Vec<u8>> { std::env::var_os(name).map(|v| std::os::unix::ffi::OsStrExt::as_bytes(&v).to_vec()) }

fn logger_use_color() -> bool {
    if env_present("NO_COLOR") { return false; }
    match env_bytes("TERM") {
        None => false,
        Some(v) => v != b"dumb",
    }
}
fn level_color_code(level: &str) -> u32 {
    match level {
        "ERROR" => 31,
        "WARN" => 33,
        "INFO" => 34,
        "DEBUG" => 36,
        "TRACE" => 35,
        _ => 0,
    }
}
fn progress_use_color() -> bool {
    if env_present("NO_COLOR") { return false; }
    if let Some(v) = env_bytes("CLICOLOR_FORCE") {
        if v != b"0" { return true; }
    }
    if let Some(v) = env_bytes("CLICOLOR") {
        if v == b"0" { return false; }
    }
    match env_bytes("TERM") {
        None => false,
        Some(v) => v != b"dumb",
    }
